update pages set contenu = '{"gabarit":"editorial","blocs":[{"type":"paragraphe","texte":"Ces fiches complètent notre [guide maintenance industrielle](/ressources/) avec des procédures applicables telles quelles : la règle, les étapes, les pièges."},{"type":"citation","texte":"Un doute sur vos procédures de maintenance ? Un chargé d''affaires vous rappelle dans l''heure, du lundi au vendredi de 8h00 à 18h30 : 04 78 33 72 05."},{"type":"titre","niveau":2,"texte":"Pourquoi ces fiches existent","id":"pourquoi-ces-fiches-existent"},{"type":"paragraphe","texte":"Chaque fiche est écrite par des techniciens qui exécutent ces gestes chaque semaine sur des sites industriels. Pas de théorie : ce qui se fait, dans l''ordre où ça se fait."},{"type":"liste","items":[{"accroche":"Écrites par le terrain, pas par un service communication.","texte":"Nos techniciens documentent les gestes qu''ils répètent chaque semaine, avec leurs pièges réels."},{"accroche":"Pensées pour l''atelier, pas pour l''écran.","texte":"Chaque fiche est imprimable et affichable au poste de travail."},{"accroche":"Un doute avant d''agir ? Un humain répond.","texte":"Un chargé d''affaires vous rappelle dans l''heure au 04 78 33 72 05, du lundi au vendredi de 8h00 à 18h30."}]},{"type":"titre","niveau":2,"texte":"Par thématique","id":"par-thematique"},{"type":"paragraphe","texte":"La sécurité d''abord, la méthode ensuite. Cinq fiches couvrent les procédures les plus demandées sur le terrain."},{"type":"tableau","entetes":["Fiche","Ce qu''elle couvre"],"lignes":[["La [consignation électrique](/ressources/fiches-pratiques/consignation-electrique/)","Séparer, condamner, vérifier l''absence de tension : la procédure qui protège l''intervenant avant tout travail sur une installation."],["Le [plan de prévention](/ressources/fiches-pratiques/plan-de-prevention/)","Le document obligatoire quand une entreprise extérieure travaille chez vous : quand le rédiger, avec qui, sur quels risques."],["Le [permis de feu](/ressources/fiches-pratiques/permis-de-feu/)","Soudage, meulage, découpe : encadrer les travaux par points chauds pour ne pas transformer une réparation en sinistre."],["La [sécurité maintenance industrielle](/ressources/fiches-pratiques/securite-maintenance/)","Les règles qui font qu''une intervention se termine sans accident, du balisage à la remise en service."],["Les [5s industrie](/ressources/fiches-pratiques/5s/)","Trier, ranger, nettoyer, standardiser, tenir dans la durée : la méthode qui rend l''atelier lisible et les anomalies visibles."]]},{"type":"titre","niveau":2,"texte":"Par où commencer","id":"par-ou-commencer"},{"type":"paragraphe","texte":"Un ordre de lecture simple, calé sur le risque : ce qui protège les personnes passe avant ce qui organise l''atelier."},{"type":"liste","items":[{"accroche":"Les fondamentaux sécurité","texte":"Consignation et plan de prévention. Ces deux procédures conditionnent toutes les autres : personne ne touche une machine sans elles."},{"accroche":"Les travaux à risque","texte":"Permis de feu et règles de sécurité en intervention. À relire avant chaque chantier ponctuel, même court."},{"accroche":"La méthode au quotidien","texte":"Les 5S. Un atelier rangé se diagnostique plus vite et cache moins de défauts."}],"ordonnee":true},{"type":"titre","niveau":2,"texte":"Ce qu''une fiche contient","id":"ce-qu-une-fiche-contient"},{"type":"paragraphe","texte":"Le même squelette partout, pour aller droit au geste : la règle, les étapes, les pièges."},{"type":"liste","items":[{"accroche":"La règle","texte":"Ce que dit la réglementation ou le standard métier, en langage clair."},{"accroche":"Les étapes","texte":"La procédure dans l''ordre d''exécution, avec les points de contrôle."},{"accroche":"Les pièges","texte":"Les erreurs que nos techniciens constatent réellement sur site."}]},{"type":"titre","niveau":2,"texte":"La règle, sans jargon","id":"la-regle-sans-jargon"},{"type":"paragraphe","texte":"Ce qui est obligatoire, ce qui est recommandé : la ligne de démarcation est écrite noir sur blanc, pour qu''aucun technicien n''ait à trancher seul sur le terrain."},{"type":"liste","items":[{"accroche":"Le texte applicable.","texte":"Norme, code du travail ou standard interne, chaque fiche cite la base de la règle."},{"accroche":"Ce qui est obligatoire.","texte":"Distingué de ce qui est recommandé, pour prioriser sous pression de temps."},{"accroche":"Ce qui reste à votre charge.","texte":"Vos consignes internes et vos habilitations restent la référence finale sur votre site."}],"ordonnee":true},{"type":"titre","niveau":2,"texte":"Les étapes, dans l''ordre d''exécution","id":"les-etapes-dans-l-ordre-d-execution"},{"type":"paragraphe","texte":"Une procédure lue en diagonale est une procédure mal appliquée. Chaque fiche est numérotée, avec les points de contrôle qui comptent."},{"type":"liste","items":[{"accroche":"Le geste, décrit sans ambiguïté.","texte":"Une action par ligne, dans l''ordre où elle s''exécute."},{"accroche":"Le point de contrôle qui suit.","texte":"Ce qu''on vérifie avant de passer à l''étape suivante."},{"accroche":"Le format imprimable.","texte":"Chaque fiche s''affiche au poste, sans reformatage."}]},{"type":"titre","niveau":2,"texte":"Les pièges à éviter","id":"les-pieges-a-eviter"},{"type":"paragraphe","texte":"Les erreurs que nos techniciens constatent réellement sur site, pas des risques théoriques."},{"type":"tableau","entetes":["Ce que nos techniciens observent","Ce que la fiche corrige"],"lignes":[["Une étape sautée par habitude","Le point de contrôle qui la rend visible avant de continuer"],["Un vocabulaire flou entre équipes","Une règle écrite, la même pour tout le monde"],["Une consigne connue mais non affichée","Une fiche imprimable, posée au poste de travail"]]},{"type":"citation","texte":"Ces fiches ne remplacent ni vos modes opératoires ni vos habilitations. Elles donnent une base saine, à adapter à vos équipements et à vos consignes internes."},{"type":"titre","niveau":2,"texte":"Questions fréquentes","id":"questions-frequentes"},{"type":"paragraphe","texte":"Les questions que nos chargés d''affaires entendent le plus souvent sur ces fiches."},{"type":"liste","items":[{"accroche":"Ces fiches remplacent-elles nos habilitations internes ?","texte":"Non. Elles donnent une base saine, à adapter à vos équipements et à vos consignes internes. Vos habilitations et vos modes opératoires restent la référence."},{"accroche":"Peut-on les imprimer et les afficher au poste ?","texte":"Oui, c''est leur usage prévu. Chaque fiche suit le même squelette, la règle, les étapes, les pièges, pensé pour être lu vite sur le terrain."},{"accroche":"Qui écrit ces fiches ?","texte":"Des techniciens Migen qui exécutent ces gestes chaque semaine sur des sites industriels, pas un service communication."},{"accroche":"Par où commencer si on n''a aucune procédure écrite ?","texte":"Par la consignation électrique et le plan de prévention : ces deux fiches conditionnent toutes les autres interventions."},{"accroche":"Une fiche manque sur un sujet précis ?","texte":"Contactez un chargé d''affaires au 04 78 33 72 05 : nous vous rappelons dans l''heure, du lundi au vendredi de 8h00 à 18h30."}]},{"type":"citation","texte":"À lire aussi : [Ressources : Fiches techniques](/ressources/fiches-techniques/)"},{"type":"citation","texte":"[Demander un diagnostic maintenance](/contact/)"}],"chapeau":"Une procédure introuvable au moment d''intervenir, c''est une intervention qui dérape."}'::jsonb where path = '/ressources/fiches-pratiques/';
